oxy_webhelp_navlinks = {"rcv_license_management-d39307e11165":{"topics":[{"title":"Rubrik Cloud Vault notifications","shortdesc":"<p class=\"shortdesc\">Rubrik sends notifications about storage capacity usage and subscription status         for Rubrik Cloud Vault locations. These notifications ensure that you can take timely         actions to maintain service availability and data protection.<\/p>","href":"saas\/rcv_notifications.html","attributes":{"data-id":"rcv_notifications"},"menu":{"hasChildren":false},"tocID":"rcv_notifications-d39307e11176","topics":[]},{"title":"Viewing the Rubrik Cloud Vault runway and forecast","shortdesc":"<p class=\"shortdesc\">View the Rubrik Cloud Vault storage runway and the 3-month consumption forecast from         the RCV dashboard to plan additional purchases or reduce usage before backups are         affected.<\/p>","href":"saas\/rcv_viewing_runway_forecast.html","attributes":{"data-id":"rcv_viewing_runway_forecast"},"menu":{"hasChildren":false},"tocID":"rcv_viewing_runway_forecast-d39307e11187","topics":[]},{"title":"Rubrik Cloud Vault storage forecast and runway","shortdesc":"<p class=\"shortdesc\">The Rubrik Cloud Vault storage forecast and runway help you monitor storage         consumption trends and plan capacity upgrades before your RCV license reaches its         limit.<\/p>","href":"saas\/rcv_runway_forecast_details.html","attributes":{"data-id":"rcv_runway_forecast_details"},"menu":{"hasChildren":false},"tocID":"rcv_runway_forecast_details-d39307e11198","topics":[]},{"title":"RCV license replacement","shortdesc":"<p class=\"shortdesc\">You can replace an existing Rubrik Cloud Vault license with a new license mid-term,         ensuring backup and archiving continuity during the transition.<\/p>","href":"saas\/rcv_license_replacement.html","attributes":{"data-id":"rcv_license_replacement"},"menu":{"hasChildren":false},"tocID":"rcv_license_replacement-d39307e11209","topics":[]}]}};